import{_ as t,o as r,c as o,l as s,t as n,N as a}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"cp | x-cmd man (man1) | copy files and directories","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | cp - copy files and directories","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"cp | x-cmd man (man1) | copy files and directories"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | cp - copy files and directories"}]]},"headers":[],"params":{"isMan":true,"man":"cp","category":"man1","desc":"copy files and directories"},"relativePath":"man1/cp.md","filePath":"man1/cp.md"}'),d={name:"man1/cp.md"},i={class:"visually-hidden"},l=a('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>cp - copy files and directories</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>cp</strong> [<em>OPTION</em>]... [<em>-T</em>] <em>SOURCE DEST</em> <br> <strong>cp</strong> [<em>OPTION</em>]... <em>SOURCE</em>... <em>DIRECTORY</em> <br> <strong>cp</strong> [<em>OPTION</em>]... <em>-t DIRECTORY SOURCE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Copy SOURCE to DEST, or multiple SOURCE(s) to DIRECTORY.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-a</strong>, <strong>--archive</strong></dt><dd>same as <strong>-dR</strong> <strong>--preserve</strong>=<em>all</em></dd><dt><strong>--attributes-only</strong></dt><dd>don&#39;t copy the file data, just the attributes</dd><dt><strong>--backup</strong>[=<em>CONTROL</em>]</dt><dd>make a backup of each existing destination file</dd><dt><strong>-b</strong></dt><dd>like <strong>--backup</strong> but does not accept an argument</dd><dt><strong>--copy-contents</strong></dt><dd>copy contents of special files when recursive</dd><dt><strong>-d</strong></dt><dd>same as <strong>--no-dereference</strong> <strong>--preserve</strong>=<em>links</em></dd><dt><strong>--debug</strong></dt><dd>explain how a file is copied. Implies <strong>-v</strong></dd><dt><strong>-f</strong>, <strong>--force</strong></dt><dd>if an existing destination file cannot be opened, remove it and try again (this option is ignored when the <strong>-n</strong> option is also used)</dd><dt><strong>-i</strong>, <strong>--interactive</strong></dt><dd>prompt before overwrite (overrides a previous <strong>-n</strong> option)</dd><dt><strong>-H</strong></dt><dd>follow command-line symbolic links in SOURCE</dd><dt><strong>-l</strong>, <strong>--link</strong></dt><dd>hard link files instead of copying</dd><dt><strong>-L</strong>, <strong>--dereference</strong></dt><dd>always follow symbolic links in SOURCE</dd><dt><strong>-n</strong>, <strong>--no-clobber</strong></dt><dd>do not overwrite an existing file (overrides a <strong>-u</strong> or previous <strong>-i</strong> option). See also <strong>--update</strong></dd><dt><strong>-P</strong>, <strong>--no-dereference</strong></dt><dd>never follow symbolic links in SOURCE</dd><dt><strong>-p</strong></dt><dd>same as <strong>--preserve</strong>=<em>mode</em>,ownership,timestamps</dd><dt><strong>--preserve</strong>[=<em>ATTR_LIST</em>]</dt><dd>preserve the specified attributes</dd><dt><strong>--no-preserve</strong>=<em>ATTR_LIST</em></dt><dd>don&#39;t preserve the specified attributes</dd><dt><strong>--parents</strong></dt><dd>use full source file name under DIRECTORY</dd><dt><strong>-R</strong>, <strong>-r</strong>, <strong>--recursive</strong></dt><dd>copy directories recursively</dd><dt><strong>--reflink</strong>[=<em>WHEN</em>]</dt><dd>control clone/CoW copies. See below</dd><dt><strong>--remove-destination</strong></dt><dd>remove each existing destination file before attempting to open it (contrast with <strong>--force</strong>)</dd><dt><strong>--sparse</strong>=<em>WHEN</em></dt><dd>control creation of sparse files. See below</dd><dt><strong>--strip-trailing-slashes</strong></dt><dd>remove any trailing slashes from each SOURCE argument</dd><dt><strong>-s</strong>, <strong>--symbolic-link</strong></dt><dd>make symbolic links instead of copying</dd><dt><strong>-S</strong>, <strong>--suffix</strong>=<em>SUFFIX</em></dt><dd>override the usual backup suffix</dd><dt><strong>-t</strong>, <strong>--target-directory</strong>=<em>DIRECTORY</em></dt><dd>copy all SOURCE arguments into DIRECTORY</dd><dt><strong>-T</strong>, <strong>--no-target-directory</strong></dt><dd>treat DEST as a normal file</dd><dt><strong>--update</strong>[=<em>UPDATE</em>]</dt><dd>control which existing files are updated; UPDATE={all,none,older(default)}. See below</dd><dt><strong>-u</strong></dt><dd>equivalent to <strong>--update</strong>[=<em>older</em>]</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>explain what is being done</dd><dt><strong>-x</strong>, <strong>--one-file-system</strong></dt><dd>stay on this file system</dd><dt><strong>-Z</strong></dt><dd>set SELinux security context of destination file to default type</dd><dt><strong>--context</strong>[=<em>CTX</em>]</dt><dd>like <strong>-Z</strong>, or if CTX is specified then set the SELinux or SMACK security context to CTX</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>ATTR_LIST is a comma-separated list of attributes. Attributes are &#39;mode&#39; for permissions (including any ACL and xattr permissions), &#39;ownership&#39; for user and group, &#39;timestamps&#39; for file timestamps, &#39;links&#39; for hard links, &#39;context&#39; for security context, &#39;xattr&#39; for extended attributes, and &#39;all&#39; for all attributes.</p><p>By default, sparse SOURCE files are detected by a crude heuristic and the corresponding DEST file is made sparse as well. That is the behavior selected by <strong>--sparse</strong>=<em>auto</em>. Specify <strong>--sparse</strong>=<em>always</em> to create a sparse DEST file whenever the SOURCE file contains a long enough sequence of zero bytes. Use <strong>--sparse</strong>=<em>never</em> to inhibit creation of sparse files.</p><p>UPDATE controls which existing files in the destination are replaced. &#39;all&#39; is the default operation when an <strong>--update</strong> option is not specified, and results in all existing files in the destination being replaced. &#39;none&#39; is similar to the <strong>--no-clobber</strong> option, in that no files in the destination are replaced, but also skipped files do not induce a failure. &#39;older&#39; is the default operation when <strong>--update</strong> is specified, and results in files being replaced if they&#39;re older than the corresponding source file.</p><p>When <strong>--reflink</strong>[=<em>always</em>] is specified, perform a lightweight copy, where the data blocks are copied only when modified. If this is not possible the copy fails, or if <strong>--reflink</strong>=<em>auto</em> is specified, fall back to a standard copy. Use <strong>--reflink</strong>=<em>never</em> to ensure a standard copy is performed.</p><p>The backup suffix is &#39;~&#39;, unless set with <strong>--suffix</strong> or SIMPLE_BACKUP_SUFFIX. The version control method may be selected via the <strong>--backup</strong> option or through the VERSION_CONTROL environment variable. Here are the values:</p><dl><dt>none, off</dt><dd>never make backups (even if <strong>--backup</strong> is given)</dd><dt>numbered, t</dt><dd>make numbered backups</dd><dt>existing, nil</dt><dd>numbered if numbered backups exist, simple otherwise</dd><dt>simple, never</dt><dd>always make simple backups</dd></dl><p>As a special case, cp makes a backup of SOURCE when the force and backup options are given and SOURCE and DEST are the same name for an existing, regular file.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Torbjorn Granlund, David MacKenzie, and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>install</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/cp%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/cp\\</a>&gt; <br> or available locally via: info &#39;(coreutils) cp invocation&#39;</p>',24);function g(e,p,c,m,h,f){return r(),o("div",null,[s("h1",i,n(e.$params.man),1),l])}const y=t(d,[["render",g]]);export{b as __pageData,y as default};
